with RecursiveRecentVotes as (
    select v.Id, v.PostId, v.VoteTypeId, v.UserId, v.CreationDate,
        u.Reputation as UserReputation,
        p.Score as PostScore,
        row_number() over (partition by v.PostId order by v.CreationDate desc) as rn
    from Votes v
    left join Users u on v.UserId = u.Id
    left join Posts p on v.PostId = p.Id
    where v.CreationDate > now() - interval '180 days'
),
RatedUserBadges as (
    select b.UserId,
           case 
               when b.Class = 1 then 'Gold'
               when b.Class = 2 then 'Silver'
               else 'Bronze'
           end BadgeClass,
           count(*) as BadgeCount,
           rating from (
              select UserId, Class, count(*) as rating
              from Badges
              group by UserId, Class
          ) desc_rating,
          sum(BadgeCount * rating) over (partition by UserId) as TotalScore
    from Badges b
),
CtrPosts as (
    select p.Id, p.PostTypeId, u.DisplayName as OwnerUserName,
       (strlen(coalesce(p.Title, '')) +
        length(coalesce(p.Tags, ''))) *
         coalesce(p.Score,p.ViewCount + 10) as StringScoreProd,
